package dev.eugheist.tc4modern;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.entity.HopperBlockEntity;
import net.minecraft.world.phys.*;
import net.minecraft.world.phys.shapes.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class ArtificeDeviceAudit {
 static final BlockPos POS=FocalAudit.BASE.offset(0,1,64),WARD=POS.east(4),TRAVEL=POS.west(4);static int ticks;static volatile boolean prepared,passed;
 static void check(boolean ok,String s){if(!ok)throw new IllegalStateException("TC4_ARTIFICE_DEVICES FAIL "+s);System.out.println("TC4_ARTIFICE_DEVICES PASS "+s);}
 static void prepare(ServerPlayer p){var l=p.serverLevel();p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.getAbilities().flying=true;p.onUpdateAbilities();p.removeAllEffects();p.getInventory().clearContent();for(var cat:thaumcraft.api.research.ResearchCategories.researchCategories.values())for(var r:cat.research.values())DevCommands.grant(p.getPersistentData(),r.key,new HashSet<>());ThaumometerItem.sync(p,"");
  for(int x=-7;x<=7;x++)for(int z=-4;z<=4;z++)for(int y=-3;y<=4;y++)l.setBlock(POS.offset(x,y,z),y==-3?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),2);
  l.setBlock(POS,ArtificeDevices.GRATE.get().defaultBlockState(),3);var open=l.getBlockState(POS);var item=new ItemEntity(l,POS.getX()+.5,POS.getY()+1,POS.getZ()+.5,new ItemStack(Items.IRON_INGOT));check(open.getCollisionShape(l,POS,CollisionContext.of(item)).isEmpty(),"open grate passes dropped items");check(!open.getCollisionShape(l,POS,CollisionContext.of(p)).isEmpty(),"open grate supports players");var closed=open.setValue(ArtificeDevices.GrateBlock.CLOSED,true);check(!closed.getCollisionShape(l,POS,CollisionContext.of(item)).isEmpty(),"closed hatch stops dropped items");
  var capability=net.neoforged.neoforge.capabilities.Capabilities.ItemHandler.BLOCK;var handler=l.getCapability(capability,POS,Direction.UP);check(handler!=null&&l.getCapability(capability,POS,Direction.DOWN)==null,"virtual inventory exposed only above");int n=l.getEntitiesOfClass(ItemEntity.class,new AABB(POS).inflate(1)).size();check(handler.insertItem(0,new ItemStack(Items.GOLD_INGOT,4),true).isEmpty()&&l.getEntitiesOfClass(ItemEntity.class,new AABB(POS).inflate(1)).size()==n,"simulated insertion spawns nothing");check(handler.extractItem(0,1,false).isEmpty(),"grate extraction always empty");
  l.setBlock(POS.west(),Blocks.REDSTONE_BLOCK.defaultBlockState(),3);check(l.getBlockState(POS).getValue(ArtificeDevices.GrateBlock.CLOSED)&&handler.insertItem(0,new ItemStack(Items.GOLD_INGOT),false).getCount()==1,"redstone closes hatch and rejects insertion");l.removeBlock(POS.west(),false);check(!l.getBlockState(POS).getValue(ArtificeDevices.GrateBlock.CLOSED),"removing power opens hatch");
  l.setBlock(POS.above(),Blocks.HOPPER.defaultBlockState(),3);((HopperBlockEntity)l.getBlockEntity(POS.above())).setItem(0,new ItemStack(Items.IRON_INGOT,4));l.setBlock(POS.below(2),Blocks.HOPPER.defaultBlockState(),3);
  l.setBlock(TRAVEL,ArtificeDevices.TRAVEL.get().defaultBlockState(),3);ArtificeDevices.TRAVEL.get().stepOn(l,TRAVEL,l.getBlockState(TRAVEL),p);check(p.getEffect(net.minecraft.world.effect.MobEffects.MOVEMENT_SPEED).getAmplifier()==1&&p.getEffect(net.minecraft.world.effect.MobEffects.JUMP).getDuration()==40&&l.getBlockState(TRAVEL).getLightEmission(l,TRAVEL)==9,"travel paving grants40tick speedII jumpI and light9");
  l.setBlock(WARD,ArtificeDevices.WARD.get().defaultBlockState(),3);var tile=(ArtificeDevices.WardEntity)l.getBlockEntity(WARD);tile.count=99;ArtificeDevices.WardEntity.tick(l,WARD,l.getBlockState(WARD),tile);check(l.getBlockState(WARD.above()).is(ArtificeDevices.FENCE.get())&&l.getBlockState(WARD.above(2)).is(ArtificeDevices.FENCE.get()),"ward stone creates two invisible fence cells");var cow=new net.minecraft.world.entity.animal.Cow(EntityType.COW,l);cow.moveTo(WARD.getX()+.5,WARD.getY()+1.2,WARD.getZ()+.5,0,0);cow.setNoAi(true);cow.setNoGravity(true);l.addFreshEntity(cow);var barrier=l.getBlockState(WARD.above());check(!barrier.getCollisionShape(l,WARD.above(),CollisionContext.of(cow)).isEmpty()&&barrier.getCollisionShape(l,WARD.above(),CollisionContext.of(p)).isEmpty()&&barrier.getCollisionShape(l,WARD.above(),CollisionContext.of(item)).isEmpty(),"barrier blocks living creatures and passes players/items");tile.count=5;cow.setDeltaMovement(Vec3.ZERO);ArtificeDevices.WardEntity.tick(l,WARD,l.getBlockState(WARD),tile);check(Math.abs(cow.getDeltaMovement().z+.2)<.001&&Math.abs(cow.getDeltaMovement().y+.1)<.001,"airborne nonplayer pushed backward and down every5ticks");l.setBlock(WARD.west(),Blocks.REDSTONE_BLOCK.defaultBlockState(),3);check(barrier.getCollisionShape(l,WARD.above(),CollisionContext.of(cow)).isEmpty(),"redstone makes creature barrier passable");check(ArtificeDevices.FENCE.get().getBlockPathType(barrier,l,WARD.above(),cow)==net.minecraft.world.level.pathfinder.PathType.OPEN,"powered barrier allows mob pathfinding");cow.discard();l.removeBlock(WARD.west(),false);
  for(var key:List.of("PaveTravel","PaveWard")){var r=ArcaneRecipes.entries().stream().filter(e->e.key().equals(key)).findFirst().orElseThrow();check(r.output().getCount()==4,"original four paving stones per craft "+key);}
  p.connection.teleport(POS.getX()+6,POS.getY()+3,POS.getZ()-7,40,25);p.getInventory().setItem(0,new ItemStack(ArtificeDevices.GRATE.get()));p.getInventory().setItem(1,new ItemStack(ArtificeDevices.TRAVEL.get()));p.getInventory().setItem(2,new ItemStack(ArtificeDevices.WARD.get()));p.getInventory().selected=8;prepared=true;
 }
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post event){if(!Boolean.getBoolean("tc4modern.artificeDeviceAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)server.execute(()->prepare(server.getPlayerList().getPlayer(id)));if(ticks==120){check(prepared,"server setup completed");LiquidDeathAudit.shot(mc,"artifice-paving-grate.png");}if(ticks==200)server.execute(()->{var l=server.overworld();var lower=(HopperBlockEntity)l.getBlockEntity(POS.below(2));int count=0;for(int i=0;i<5;i++)if(lower.getItem(i).is(Items.IRON_INGOT))count+=lower.getItem(i).getCount();check(count==4,"actual hopper transfers4items through virtual grate into lower hopper");passed=true;});if(ticks==210){check(passed,"native hopper test completed");var inv=mc.player.getInventory();mc.setScreen(new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,net.minecraft.network.chat.Component.empty()));}if(ticks>=220&&ticks<=240&&ticks%10==0)((ThaumonomiconScreen)mc.screen).auditOpen(thaumcraft.api.research.ResearchCategories.getResearch(List.of("GRATE","PAVETRAVEL","PAVEWARD").get((ticks-220)/10)),0);if(ticks>=225&&ticks<=245&&ticks%10==5)LiquidDeathAudit.shot(mc,"artifice-device-book-"+(ticks-225)/10+".png");if(ticks==250)mc.stop();}
}
